package com.guangyingruoshui.imagetools;

import android.app.AlertDialog;
import android.content.*;
import android.graphics.*;
import android.view.View;
import android.widget.*;
import java.io.*;
import java.util.*;
import org.json.*;

/** Device regressions for desktop/mobile shared controls, not host bitmap stubs. */
final class ParityTests {
    static void require(boolean value,String message)throws IOException{if(!value)throw new IOException(message);}
    static CheckBox checkbox(View view,String name){if(view instanceof CheckBox&&((CheckBox)view).getText().toString().equals(name))return (CheckBox)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){CheckBox found=checkbox(group.getChildAt(i),name);if(found!=null)return found;}}return null;}
    static File image(File dir,String name,int color,Files.Job job)throws Exception{Bitmap bitmap=Bitmap.createBitmap(48,36,Bitmap.Config.ARGB_8888);bitmap.eraseColor(color);File out=new File(dir,name);try{Images.encode(bitmap,out,0,job);}finally{bitmap.recycle();}return out;}
    static void waitIdle(MainActivity m)throws Exception{long deadline=System.currentTimeMillis()+10000;while(m.busy&&System.currentTimeMillis()<deadline)Thread.sleep(30);require(!m.busy,"Parity async task timed out");UiTests.frames(m);}
    static void run(MainActivity m,File dir,Files.Job job,StringBuilder report)throws Exception {
        require(ColorPicker.parse("#12aB89")==0xff12ab89&&ColorPicker.parse("7F204060")==0x7f204060,"Arbitrary color parser mismatch");try{ColorPicker.parse("#xyz");throw new IOException("Invalid color accepted");}catch(IllegalArgumentException expected){}
        final int[] color={0};final AlertDialog[] colorDialog={null};
        UiTests.ui(m,()->colorDialog[0]=ColorPicker.show(m,"color regression",Color.BLACK,value->color[0]=value));UiTests.frames(m);
        UiTests.ui(m,()->{AlertDialog dialog=colorDialog[0];EditText value=dialog.getWindow().getDecorView().findViewWithTag("color-value");value.setText("invalid");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});UiTests.frames(m);
        UiTests.ui(m,()->{AlertDialog dialog=colorDialog[0];if(!dialog.isShowing()||color[0]!=0)throw new IllegalStateException("Invalid color dialog accepted or dismissed");EditText value=dialog.getWindow().getDecorView().findViewWithTag("color-value");value.setText("#FF206890");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});UiTests.frames(m);
        UiTests.ui(m,()->{if(colorDialog[0].isShowing()||color[0]!=0xff206890)throw new IllegalStateException("Exact custom color not applied");m.showPage(5);if(UiTests.buttonNamed(m.pages[5],m.t("选择遮盖颜色…","Choose cover color…"))==null)throw new IllegalStateException("Cover color button absent");});
        final int[] oldEffect={0},oldColor={0};UiTests.ui(m,()->{oldEffect[0]=m.editor.effect;oldColor[0]=m.editor.coverColor;Bitmap original=Bitmap.createBitmap(48,36,Bitmap.Config.ARGB_8888);original.eraseColor(Color.GREEN);m.editor.set(original);m.editor.effect=2;m.editor.coverColor=0xff206890;Paint brush=new Paint();brush.setColor(Color.WHITE);m.editor.maskCanvas.drawRect(10,10,30,28,brush);});Bitmap covered=m.editor.apply(job);try{require(covered.getPixel(20,20)==0xff206890,"Selected custom cover color not rendered");require(covered.getPixel(0,0)==Color.GREEN&&covered.getWidth()==48&&covered.getHeight()==36,"Custom cover damaged outside selection or canvas");}finally{covered.recycle();UiTests.ui(m,()->{m.editor.effect=oldEffect[0];m.editor.coverColor=oldColor[0];m.editor.clear();});}
        UiTests.ui(m,()->{m.showPage(0);if(UiTests.buttonNamed(m.pages[0],m.t("自选文字颜色…","Custom text color…"))==null)throw new IllegalStateException("Text color entry absent");m.showPage(7);if(UiTests.buttonNamed(m.pages[7],m.t("自选留边颜色…","Custom padding color…"))==null)throw new IllegalStateException("Padding color entry absent");});report.append("PASS: real color dialog rejects invalid HEX, applies exact arbitrary RGBA; custom solid cover preserves full canvas/outside pixels; text and padding controls exist\n");

        File first=image(dir,"parity-frame-red.png",Color.RED,job),second=image(dir,"parity-frame-blue.png",Color.BLUE,job);ArrayList<MainActivity.Entry> saved=new ArrayList<>(m.state[3].entries);int delay=m.state[3].gifDelay;boolean looping=m.state[3].gifLoop;
        MainActivity.State batchState=m.state[4];ArrayList<MainActivity.Entry> previousEntries=new ArrayList<>(batchState.entries);Set<MainActivity.Entry> previousChecks=new HashSet<>(batchState.checked);try{UiTests.ui(m,()->{m.showPage(4);batchState.entries.clear();batchState.checked.clear();MainActivity.Entry one=new MainActivity.Entry(first),two=new MainActivity.Entry(second),three=new MainActivity.Entry(first);batchState.entries.add(one);batchState.entries.add(two);batchState.entries.add(three);batchState.selected=1;m.refreshQueue(batchState);if(m.snapshot(batchState,true).size()!=3||m.snapshot(batchState,false).get(0)!=two)throw new IllegalStateException("Unchecked batch/current defaults changed");ListView queue=m.queues.get(batchState);View row0=queue.getAdapter().getView(0,null,queue),row2=queue.getAdapter().getView(2,null,queue);((CheckBox)((LinearLayout)row0).getChildAt(0)).performClick();((CheckBox)((LinearLayout)row2).getChildAt(0)).performClick();List<MainActivity.Entry> subset=m.snapshot(batchState,true);if(subset.size()!=2||subset.get(0)!=one||subset.get(1)!=three||m.snapshot(batchState,false).size()!=2)throw new IllegalStateException("Checkboxes did not select arbitrary batch subset");Collections.swap(batchState.entries,0,2);m.refreshQueue(batchState);subset=m.snapshot(batchState,true);if(subset.get(0)!=three||subset.get(1)!=one)throw new IllegalStateException("Checked entries lost identity after reorder");UiTests.buttonNamed(m.pages[4],m.t("移除选中","Remove selected")).performClick();if(batchState.entries.size()!=1||batchState.entries.get(0)!=two||!batchState.checked.isEmpty())throw new IllegalStateException("Remove did not remove checked subset only");UiTests.buttonNamed(m.pages[4],m.t("清空队列","Clear queue")).performClick();if(!batchState.entries.isEmpty()||!batchState.checked.isEmpty())throw new IllegalStateException("Clear retained selections");});}finally{UiTests.ui(m,()->{batchState.entries.clear();batchState.entries.addAll(previousEntries);batchState.checked.clear();batchState.checked.addAll(previousChecks);m.refreshQueue(batchState);});}report.append("PASS: production checkboxes select nonadjacent entries, snapshots preserve queue order/entry identity, and Remove/Clear handle marks; unchecked batch uses all and selected uses current\n");
        File portrait=new File(dir,"parity-cover-portrait.png");Bitmap source=Bitmap.createBitmap(84,140,Bitmap.Config.ARGB_8888);source.eraseColor(0xff35936c);source.setPixel(0,0,Color.RED);source.setPixel(83,139,Color.BLUE);try{Images.encode(source,portrait,0,job);}finally{source.recycle();}String originalHash=Files.hash(portrait,job);MainActivity.State coverOptions=new MainActivity.State();coverOptions.cover=portrait;Bitmap cover=m.makeFileCover(coverOptions,null,0,0,false);try{require(cover.getWidth()==84&&cover.getHeight()==140&&cover.getPixel(0,0)==Color.RED&&cover.getPixel(83,139)==Color.BLUE,"File cover cropped, letterboxed or stretched original");byte[] jpeg=Archive.cover(cover,dir,job);Bitmap decoded=BitmapFactory.decodeByteArray(jpeg,0,jpeg.length);try{require(decoded!=null&&decoded.getWidth()==84&&decoded.getHeight()==140,"Packaged JPEG cover lost source ratio");}finally{if(decoded!=null)decoded.recycle();}}finally{cover.recycle();}coverOptions.cover=null;cover=m.makeFileCover(coverOptions,null,0,1600,false);try{require(cover.getWidth()==800&&cover.getHeight()==500,"Default file cover dimensions differ from desktop");}finally{cover.recycle();}require(Files.hash(portrait,job).equals(originalHash),"Cover conversion changed original image");report.append("PASS: actual portrait cover retains original dimensions/corner pixels and JPEG aspect ratio, default cover is 800×500, and original SHA remains intact\n");
        try{UiTests.ui(m,()->{m.showPage(3);MainActivity.State s=m.state[3];s.entries.clear();s.entries.add(new MainActivity.Entry(first));s.entries.add(new MainActivity.Entry(second));s.selected=0;s.gifDelay=40;s.gifLoop=false;m.refreshQueue(s);Button play=UiTests.buttonNamed(m.pages[3],m.t("开始播放","Play preview"));if(play==null)throw new IllegalStateException("GIF play button absent");play.performClick();});long deadline=System.currentTimeMillis()+10000;while(m.gifPlayer.presented<2&&System.currentTimeMillis()<deadline)Thread.sleep(40);UiTests.frames(m);UiTests.ui(m,()->{GifPreviewPlayer p=m.gifPlayer;if(p.presented!=2||p.lastFrame!=1||p.preview.image.getPixel(20,20)!=Color.BLUE)throw new IllegalStateException("GIF actual frames not loaded in order");if(m.state[3].entries.get(0).file!=first||m.state[3].entries.get(1).file!=second)throw new IllegalStateException("Playback reordered queue");m.state[3].gifLoop=true;p.start();});Thread.sleep(100);UiTests.ui(m,()->{m.showPage(7);if(m.gifPlayer.running)throw new IllegalStateException("Hidden GIF page continued playing");});}
        finally{UiTests.ui(m,()->{if(m.gifPlayer!=null)m.gifPlayer.stop();m.state[3].entries.clear();m.state[3].entries.addAll(saved);m.state[3].gifDelay=delay;m.state[3].gifLoop=looping;m.refreshQueue(m.state[3]);});}report.append("PASS: GIF Play button loads real red/blue frames sequentially without changing queue; non-loop playback stops and hiding page stops looping\n");

        File tagged=new File(dir,"parity-tags.png");String graph="{\"1\":{\"class_type\":\"CLIPTextEncode\",\"inputs\":{\"text\":\"parity positive\"}},\"2\":{\"class_type\":\"CLIPTextEncode\",\"inputs\":{\"text\":\"parity negative\"}},\"3\":{\"class_type\":\"KSampler\",\"inputs\":{\"positive\":[\"1\",0],\"negative\":[\"2\",0],\"seed\":1234567890123456789,\"steps\":22}}}";
        try(InputStream in=new FileInputStream(first);OutputStream out=new FileOutputStream(tagged)){out.write(Files.PNG);Files.read(in,8);byte[] header=Files.read(in,8);int n=(int)Files.be(header,0,4);out.write(header);out.write(Files.read(in,n+4));Files.chunk(out,"tEXt",Files.concat("parameters\0".getBytes(Files.LATIN),"parity web positive\nNegative prompt: bad\nSteps: 20, Seed: 1234567890123456789".getBytes(Files.LATIN)));Files.chunk(out,"iTXt",Files.concat("prompt\0".getBytes(Files.LATIN),new byte[4],graph.getBytes(Files.UTF8)));Files.copy(in,out,job);}
        Metadata.Result previousWeb=m.webInfo,previousComfy=m.comfyInfo;try{UiTests.ui(m,()->{m.showPage(6);if(UiTests.buttonNamed(m.pages[6],m.t("选择图片并读取两栏","Open image and read both panels"))==null)throw new IllegalStateException("Read both picker absent");m.readBothTags(tagged);});waitIdle(m);UiTests.ui(m,()->{if(m.webInfo!=m.comfyInfo||m.webInfo.web.isEmpty()||m.comfyInfo.comfy.isEmpty())throw new IllegalStateException("Single metadata read did not populate both panels");String value=m.allTags();if(!value.contains("parity web positive")||!value.contains("parity positive")||!value.contains("1234567890123456789"))throw new IllegalStateException("Copy all omitted fields or exact seed");Button copy=UiTests.buttonNamed(m.pages[6],m.t("复制全部参数","Copy all parameters"));copy.performClick();ClipboardManager clipboard=(ClipboardManager)m.getSystemService(Context.CLIPBOARD_SERVICE);if(!clipboard.hasPrimaryClip()||!value.contentEquals(clipboard.getPrimaryClip().getItemAt(0).getText()))throw new IllegalStateException("Copy all button did not put full content on clipboard");});}finally{UiTests.ui(m,()->{m.webInfo=previousWeb;m.comfyInfo=previousComfy;});}report.append("PASS: one actual PNG metadata read populates WebUI and ComfyUI; Copy all button copies both panels and exact 64-bit seed\n");

        SharedPreferences prefs=m.prefs;boolean album=prefs.getBoolean("album",true);String tree=prefs.getString("tree","");try{UiTests.ui(m,()->{prefs.edit().putBoolean("album",true).apply();Intent gallery=m.outputFolderIntent();if(!Intent.ACTION_VIEW.equals(gallery.getAction())||!"image/*".equals(gallery.getType()))throw new IllegalStateException("Album destination did not build gallery intent");prefs.edit().putBoolean("album",false).putString("tree","content://com.android.externalstorage.documents/tree/primary%3APictures").apply();Intent folder=m.outputFolderIntent();if(!android.provider.DocumentsContract.Document.MIME_TYPE_DIR.equals(folder.getType())||!folder.getDataString().contains("document/"))throw new IllegalStateException("SAF destination did not build directory view");m.showPage(7);if(UiTests.buttonNamed(m.pages[7],m.t("打开保存位置","Open destination"))==null)throw new IllegalStateException("Destination entry missing");});}finally{prefs.edit().putBoolean("album",album).putString("tree",tree).apply();}report.append("PASS: album and SAF directory produce actual platform viewing intents and Open destination control\n");
        int defaultBound=prefs.getInt("dualDefaultBound",1200);boolean defaultNumber=prefs.getBoolean("dualDefaultNumbered",false),defaultLoop=prefs.getBoolean("loop",true);try{UiTests.ui(m,()->{m.showPage(7);Spinner size=m.pages[7].findViewWithTag("dual-default-size");if(size==null)throw new IllegalStateException("Default size control absent");size.setSelection(2);CheckBox number=checkbox(m.pages[7],m.t("双图默认自动编号","Number dual images by default")),loop=checkbox(m.pages[7],m.t("GIF 默认循环播放","Loop GIFs by default"));if(number==null||loop==null)throw new IllegalStateException("Default boolean controls absent");number.setChecked(true);loop.setChecked(false);});UiTests.frames(m);UiTests.ui(m,()->{MainActivity.State next=new MainActivity.State();m.loadDualDefaults(next);if(next.bound!=3200||!next.numbered||prefs.getBoolean("loop",true))throw new IllegalStateException("Actual default controls did not persist/load");});}finally{prefs.edit().putInt("dualDefaultBound",defaultBound).putBoolean("dualDefaultNumbered",defaultNumber).putBoolean("loop",defaultLoop).apply();}report.append("PASS: actual default-size/numbering/GIF-loop controls persist and apply to new settings\n");

        JSONObject equal=QQRoundTrip.inspect(first,first,"test-client","group",true,job);require(equal.getBoolean("byteIdentical")&&equal.getBoolean("verifiedOriginalRoundTrip"),"Identical roundtrip not verified");JSONObject different=QQRoundTrip.inspect(first,second,"test-client","group",true,job);require(!different.getBoolean("byteIdentical")&&!different.getBoolean("verifiedOriginalRoundTrip"),"Changed roundtrip claimed compatible");JSONObject unconfirmed=QQRoundTrip.inspect(first,first,"test-client","group",false,job);require(!unconfirmed.getBoolean("verifiedOriginalRoundTrip"),"Unconfirmed original transfer certified");try{QQRoundTrip.inspect(first,first,"","group",true,job);throw new IOException("Client version omitted");}catch(IOException expected){if(expected.getMessage().equals("Client version omitted"))throw expected;}UiTests.ui(m,()->{m.showPage(2);if(UiTests.buttonNamed(m.pages[2],m.t("QQ 原图往返校验…","QQ original round-trip check…"))==null)throw new IllegalStateException("QQ roundtrip entry absent");AlertDialog dialog=QQRoundTrip.show(m);if(UiTests.buttonNamed(dialog.getWindow().getDecorView(),m.t("校验并导出 JSON 报告","Verify and export JSON report"))==null)throw new IllegalStateException("QQ actual export control absent");dialog.dismiss();});report.append("PASS: QQ actual SHA/byte reports distinguish identical, changed and unconfirmed originals, require client version, and expose real verification/export dialog\n");
    }
}
